extern alias game;
using System.Text.Json;
using ProtoBuf;
internal static class RankingAudit {
 public static void Run(string root){var c=new GameCatalog(root);using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"LocalServer/data/tables/manifest.json")));var row=manifest.RootElement.EnumerateArray().Single(x=>x.GetProperty("id").GetInt32()==game::CUtil.GenerateHashKey("TextLocalDataTable_zh_CN"));using var f=File.OpenRead(Path.Combine(root,"LocalServer/data/tables",row.GetProperty("name").GetString()+".pb"));var texts=Serializer.Deserialize<BscTable.LocalTextDataTable>(f);texts.MakeMap();var keys=new[]{"Message.Board.Sub.Empower","Label.Board.Score.EmpowerPoint","Message.Board.Sub.GiuldDonationPoint","Label.Board.Score.GiuldDonationPoint","Message.Board.Sub.Buy","Message.Board.Sub.Buy.Daily","Label.Board.Score.BuyPoint","Message.Board.Sub.WanderPoint","Label.Board.Score.WanderPoint","Message.Board.Sub.BattleArena.RealTime","Message.Board.Sub.TotalPower.AllCard"};File.WriteAllText(Path.Combine(root,"evidence/ranking-original-catalog.json"),JsonSerializer.Serialize(new{initialHeroCount=c.InitialHeroes.Count(),unusualInitialHeroes=c.InitialHeroes.Where(x=>x.Rank!=1||x.Id!=x.EvolveFirstAncestor).Select(x=>new{x.Id,x.Rank,x.EvolveFirstAncestor}),text=keys.ToDictionary(x=>x,x=>texts.GetItem(x)?.Text),numbers=c.Numbers.Where(x=>x.Key.ToString().Contains("LIKE")).ToDictionary(x=>x.Key.ToString(),x=>x.Value),types=Enum.GetValues<BscTable.RANKING_BOARD_TYPE>().ToDictionary(x=>x.ToString(),x=>(int)x)},new JsonSerializerOptions{WriteIndented=true}));}
}
